{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "A structurally related reversible MAGL tracer was peripherally restricted with low brain accumulation despite specific MAGL binding; this is the closest contradictory anchor, but its higher polarity, basic piperazine, and larger scaffold limit transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "[18F]FCWAY, a fluorinated amide PET tracer containing pyridine and N-heterocycles, is BBB-permeable in rodents and humans, supporting CNS access for the query's fluorinated amide/heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A compound with a pyridine/fluorophenyl-pyrazole amide showed brain and CSF penetration and low P-glycoprotein susceptibility, supporting that the query's pyridine-pyrazole amide motif can access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Praziquantel, a lipophilic amide with a saturated ring, reached brain concentrations of 5.7 µg/g after intravenous dosing in rats, demonstrating that amide-containing small molecules of similar size can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "PNU282987, a chlorophenyl amide, showed good brain penetration after intravenous injection, supporting CNS access for chlorinated aromatic amide-containing compounds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query has favorable passive CNS properties (MW 362, logD ~2.3, TPSA 54, no HBD, neutral at pH 7.4) and is supported by transferable evidence from brain-permeable fluorinated amide/heteroaromatic analogues. The closest peripherally-restricted MAGL tracer is structurally divergent and lacks the query's favorable neutral, low-TPSA profile, so meaningful CNS access is likely.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or PET measurement exists for the query itself.",
    "All experimental analogues have low Morgan similarity (<0.26), limiting quantitative transfer.",
    "Efflux-transporter status of the query is inferred only from physicochemical prior, not measured.",
    "The [18F] radiolabel may alter metabolic/distribution behavior relative to unlabeled analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

